142	    /**
143	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
144	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
145	     * a city that is not listed has no known region and accepts any 4-digit postcode.
146	     */
147	    private static final Map<String, String> CITY_REGIONS = Map.of(
148	        "Sydney", "NSW",
149	        "Melbourne", "VIC",
150	        "Brisbane", "QLD");
151	
152	    /**
153	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
154	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
155	     */
156	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
157	        "NSW", new int[] {2000, 2099},
158	        "VIC", new int[] {3000, 3099},
159	        "QLD", new int[] {4000, 4099});
