223	    /**
224	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
225	     * upper-cases the value, and expands common street-type abbreviations word-by-word
226	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
227	     * normalizes to the empty string. The normalized value is what the application stores, returns
228	     * and compares for household detection.
229	     *
230	     * @param address the raw address value from the request, may be {@code null}
231	     * @return the normalized address, or the empty string when none was supplied
232	     */
233	    private String normalizeAddress(String address) {
234	        if (address == null) {
235	            return "";
236	        }
237	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
238	        if (collapsed.isEmpty()) {
239	            return "";
240	        }
241	        String[] tokens = collapsed.split(" ");
242	        StringBuilder normalized = new StringBuilder();
243	        for (int i = 0; i < tokens.length; i++) {
244	            if (i > 0) {
245	                normalized.append(' ');
246	            }
247	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
248	        }
249	        return normalized.toString();
250	    }
251	
252	    /**
253	     * Applies address normalization to whichever address form the request supplied, preferring the
254	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
255	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
256	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
257	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
258	     * appended - so everything downstream that reads {@code address} sees the structured value. When
259	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
260	     * earlier minimal owners backward-compatible.
261	     *
262	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
263	     */
264	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
265	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
266	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
267	            ownerFieldsDto.setAddressLine1(line1);
268	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
269	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
270	                ownerFieldsDto.setAddressLine2(line2);
271	                ownerFieldsDto.setAddress(line1 + " " + line2);
272	            } else {
273	                ownerFieldsDto.setAddressLine2(null);
274	                ownerFieldsDto.setAddress(line1);
275	            }
276	        } else {
277	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
278	        }
279	    }
280	
281	    /**
282	     * Rejects an owner payload that is missing or blank in any required field. The response body's
283	     * {@code errors} array lists the name of each offending field.
284	     *
285	     * @param ownerFieldsDto the owner payload to validate
286	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
287	     */
288	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
289	        List<String> missingFields = new ArrayList<>();
290	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
291	            missingFields.add("firstName");
292	        }
293	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
294	            missingFields.add("lastName");
295	        }
296	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
297	            missingFields.add("address");
298	        }
299	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
300	            missingFields.add("city");
301	        }
302	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
303	            missingFields.add("telephone");
304	        }
305	        if (!missingFields.isEmpty()) {
306	            throw new RequiredFieldsMissingException(missingFields);
307	        }
308	    }
309	
310	    /**
311	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
312	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
313	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
314	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
315	     * region accepts any 4-digit postcode.
316	     *
317	     * @param postcode the raw postcode value from the request, may be {@code null}
318	     * @param city the owner's city, used to look up the region whose range constrains the postcode
319	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
320	     */
321	    private void validatePostcode(String postcode, String city) {
322	        if (postcode == null) {
323	            return;
324	        }
325	        if (!postcode.matches("[0-9]{4}")) {
326	            throw new InvalidFieldsException(List.of("postcode"));
327	        }
328	        String region = CITY_REGIONS.get(city);
329	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
330	        if (range != null) {
331	            int value = Integer.parseInt(postcode);
332	            if (value < range[0] || value > range[1]) {
333	                throw new InvalidFieldsException(List.of("postcode"));
334	            }
335	        }
336	    }
337	
338	    /**
339	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
340	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
341	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
342	     * followed by 8 to 15 digits.
343	     *
344	     * @param telephone the raw telephone value from the request
345	     * @return the E.164 telephone (e.g. {@code +61412345678})
346	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
347	     */
348	    private String normalizeTelephone(String telephone) {
349	        if (telephone == null) {
350	            throw new InvalidFieldsException(List.of("telephone"));
351	        }
352	        String trimmed = telephone.trim();
353	        boolean international = trimmed.startsWith("+");
354	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
355	        String digits;
356	        if (international) {
357	            digits = cleaned.substring(1);
358	        } else {
359	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
360	            digits = "61" + national;
361	        }
362	        if (!digits.matches("[0-9]{8,15}")) {
363	            throw new InvalidFieldsException(List.of("telephone"));
364	        }
365	        requireValidNationalLength(digits);
366	        return "+" + digits;
367	    }
368	
369	    /**
370	     * Country codes with a fixed national-number length, checked longest-prefix first so that
371	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
372	     * digits; the North American Numbering Plan ('1') requires 10.
373	     */
374	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
375	
376	    /**
377	     * Validates that the national number (the E.164 digits after the country code) has the length
378	     * required for its country. Country codes without a known fixed length are left to the general
379	     * E.164 length check.
380	     *
381	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
382	     * @throws InvalidFieldsException if the national number is the wrong length for its country
383	     */
384	    private void requireValidNationalLength(String digits) {
385	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
386	            .filter(entry -> digits.startsWith(entry.getKey()))
387	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
388	            .ifPresent(entry -> {
389	                int nationalLength = digits.length() - entry.getKey().length();
390	                if (nationalLength != entry.getValue()) {
391	                    throw new InvalidFieldsException(List.of("telephone"));
392	                }
393	            });
394	    }
395	
396	    /**
397	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
398	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
399	     * be a syntactically valid address; the accepted value is returned lower-cased.
400	     *
401	     * @param email the raw email value from the request, may be {@code null}
402	     * @return the lower-cased email, or {@code null} when none was supplied
403	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
404	     */
405	    private String normalizeEmail(String email) {
406	        if (email == null || email.isBlank()) {
407	            return null;
408	        }
409	        String trimmed = email.trim();
410	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
411	            throw new InvalidFieldsException(List.of("email"));
412	        }
413	        String normalized = trimmed.toLowerCase(Locale.ROOT);
414	        String domain = normalized.substring(normalized.indexOf('@') + 1);
415	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
416	            throw new InvalidFieldsException(List.of("email"));
417	        }
418	        return normalized;
419	    }
420	
421	    /**
422	     * Tests whether an existing owner is not soft-deleted, so that duplicate and identity detection
423	     * can ignore owners flagged {@code deleted}. An owner whose {@code deleted} flag is {@code null}
424	     * or {@code false} is considered active; only an explicit {@code true} excludes it.
425	     *
426	     * @param owner an existing owner from the data store
427	     * @return {@code true} when the owner is not flagged deleted, otherwise {@code false}
428	     */
429	    private static boolean isNotDeleted(Owner owner) {
430	        return !Boolean.TRUE.equals(owner.getDeleted());
431	    }
432	
433	    private void requireUniqueIdentity(Owner owner) {
434	        String identityKey = ownerMapper.identityKey(owner);
435	        boolean taken = this.clinicService.findAllOwners().stream()
436	            .filter(OwnerRestControllerV1::isNotDeleted)
437	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
438	        if (taken) {
439	            throw new DuplicateOwnerIdentityException(identityKey);
440	        }
441	    }
442	
443	    /**
444	     * Computes the membership level ceiling for the owner being created: one above the current
445	     * maximum membership level among the existing members of the owner's household (those sharing its
446	     * computed {@link OwnerMapper#householdId(Owner) household id}, ignoring soft-deleted owners). Each
447	     * existing member's level is evaluated for the household size that now includes the joining owner,
448	     * so the ceiling reflects the household's up-to-date standing. Returns {@code null} when the
449	     * household has no existing member, in which case no cap applies. Invoked before the new owner is
450	     * persisted, so it never counts the owner itself.
451	     *
452	     * @param owner the owner being created, with its normalized fields already applied
453	     * @return the capped maximum membership level, or {@code null} when no existing household member
454	     */
455	    private Integer householdMembershipLevelCap(Owner owner) {
456	        String householdId = ownerMapper.householdId(owner);
457	        List<Owner> members = this.clinicService.findAllOwners().stream()
458	            .filter(OwnerRestControllerV1::isNotDeleted)
459	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
460	            .toList();
461	        if (members.isEmpty()) {
462	            return null;
463	        }
464	        int householdSize = members.size() + 1;
465	        int maxLevel = members.stream()
466	            .mapToInt(existing -> ownerMapper.householdMemberLevel(existing, householdSize))
467	            .max()
468	            .getAsInt();
469	        return maxLevel + 1;
470	    }
471	
472	    /**
473	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
474	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
475	     * normalizes to the empty string.
476	     *
477	     * @param value the raw field value, may be {@code null}
478	     * @return the trimmed, whitespace-collapsed, lower-cased form
479	     */
480	    private String normalizeHousehold(String value) {
481	        if (value == null) {
482	            return "";
483	        }
484	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
485	    }
486	
487	    /**
488	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
489	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}, so its
490	     * identity key differs from the new owner's) but shares the new owner's surname phonetically -
491	     * the same {@link Soundex Soundex} code for the last name - and the same postcode. Only owners
492	     * with a postcode participate: when the new owner has no postcode there is nothing to soft-match
493	     * on. When several existing owners match, the one with the lowest id is returned so the result is
494	     * deterministic.
495	     *
496	     * @param owner the owner being created, with its normalized telephone already applied
497	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
498	     */
499	    private Owner findPossibleDuplicate(Owner owner) {
500	        String lastName = owner.getLastName();
501	        String postcode = owner.getPostcode();
502	        if (lastName == null || postcode == null) {
503	            return null;
504	        }
505	        String soundex = Soundex.encode(lastName);
506	        String identityKey = ownerMapper.identityKey(owner);
507	        return this.clinicService.findAllOwners().stream()
508	            .filter(OwnerRestControllerV1::isNotDeleted)
509	            .filter(existing -> postcode.equals(existing.getPostcode()))
510	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
511	            .filter(existing -> !identityKey.equals(ownerMapper.identityKey(existing)))
512	            .min(Comparator.comparingInt(Owner::getId))
513	            .orElse(null);
514	    }
515	
516	    /**
517	     * Rejects an owner whose city already contains the maximum permitted number of owners
518	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
519	     * the same normalization used for the other owner household fields.
520	     *
521	     * @param city the city of the owner being created
522	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
523	     */
524	    private void requireCityHasCapacity(String city) {
525	        String normalizedCity = normalizeHousehold(city);
526	        long count = this.clinicService.findAllOwners().stream()
527	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
528	            .count();
529	        if (count >= CITY_CAPACITY) {
530	            throw new CityAtCapacityException(city);
531	        }
532	    }
533	
534	    /**
535	     * Rejects creating an owner once the given business day has already reached the maximum
536	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
537	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
538	     * registration date.
539	     *
540	     * @param registrationDate the business-day-adjusted registration date of the owner being created
541	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
542	     *     registered on that business day
543	     */
544	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
545	        long count = this.clinicService.findAllOwners().stream()
546	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
547	            .count();
548	        if (count >= DAILY_OWNER_LIMIT) {
549	            throw new DailyOwnerLimitException(registrationDate);
550	        }
551	    }
552	
553	    /**
554	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
555	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
556	     * been registered on that date. Evaluated before the new owner is persisted, so the count
557	     * reflects the owners that existed at the time of creation.
558	     *
559	     * @param registrationDate the business-day-adjusted registration date of the owner being created
560	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
561	     *     that registration date, otherwise {@code false}
562	     */
563	    private boolean isBulkSignup(LocalDate registrationDate) {
564	        long count = this.clinicService.findAllOwners().stream()
565	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
566	            .count();
567	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
568	    }
569	
570	    /**
571	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
572	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
573	     * date in the future is invalid.
574	     *
575	     * @param registrationDate the registration date supplied on the request, may be {@code null}
576	     * @throws InvalidFieldsException if the supplied date is later than today's server date
577	     */
578	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
579	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
580	            throw new InvalidFieldsException(List.of("registrationDate"));
581	        }
582	    }
583	
584	    /**
585	     * Rolls a registration date forward onto a business day: any Saturday, Sunday or listed public
586	     * holiday is advanced day by day until the first weekday that is not a public holiday, while a
587	     * plain weekday is returned unchanged.
588	     *
589	     * @param date the effective registration date (supplied or defaulted to the server date)
590	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
591	     */
592	    private LocalDate toBusinessDay(LocalDate date) {
593	        LocalDate result = date;
594	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
595	            result = result.plusDays(1);
596	        }
597	        return result;
598	    }
599	
600	    private boolean isWeekend(LocalDate date) {
601	        return switch (date.getDayOfWeek()) {
602	            case SATURDAY, SUNDAY -> true;
603	            default -> false;
604	        };
605	    }
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Override
609	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
610	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
611	        if (StringUtils.hasText(idempotencyKey)) {
612	            Integer existingId = idempotentCreates.get(idempotencyKey);
613	            if (existingId != null) {
614	                Owner existing = this.clinicService.findOwnerById(existingId);
615	                if (existing != null) {
616	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
617	                }
618	            }
619	        }
620	        applyAddressFields(ownerFieldsDto);
621	        validateRequiredFields(ownerFieldsDto);
622	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
623	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
624	        requireCityHasCapacity(ownerFieldsDto.getCity());
625	        String email = normalizeEmail(ownerFieldsDto.getEmail());
626	        HttpHeaders headers = new HttpHeaders();
627	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
628	        owner.setTelephone(telephone);
629	        owner.setEmail(email);
630	        owner.setDeleted(false);
631	        requireUniqueIdentity(owner);
632	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
633	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
634	        LocalDate effectiveDate = owner.getRegistrationDate() != null
635	            ? owner.getRegistrationDate() : LocalDate.now();
636	        LocalDate registrationDate = toBusinessDay(effectiveDate);
637	        owner.setRegistrationDate(registrationDate);
638	        requireDailyLimitNotReached(registrationDate);
639	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
640	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
641	        owner.setPossibleDuplicate(possibleDuplicate != null);
642	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
643	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner));
644	        this.clinicService.saveOwner(owner);
645	        if (StringUtils.hasText(idempotencyKey)) {
646	            idempotentCreates.put(idempotencyKey, owner.getId());
647	        }
648	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
649	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
650	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
651	        AUDIT.info("{}", new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(),
652	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner)).toJson());
653	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
654	        headers.setLocation(UriComponentsBuilder.newInstance()
655	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
656	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
657	    }
658	
659	    /**
660	     * The owner's current primary identifier as carried by the structured {@code OWNER_CREATED}
661	     * audit event. Today this is the {@code customerCode}; when the customer code is later unified
662	     * into a member id, this is the single place that changes so the event automatically switches to
663	     * carrying the {@code memberId} instead.
664	     */
665	    private String primaryIdentifier(Owner owner) {
666	        return owner.getCustomerCode();
667	    }
668	
669	    /**
670	     * Immutable structured record of a successful owner creation, serialized as a single JSON object
671	     * to the {@code AUDIT} logger alongside the human-readable audit line. The {@code customerCode}
672	     * field carries the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}).
673	     */
674	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
675	                                     Integer membershipLevel) {
676	
677	        String toJson() {
678	            return "{\"seq\":" + seq
679	                + ",\"ownerId\":" + ownerId
680	                + ",\"customerCode\":" + jsonString(customerCode)
681	                + ",\"membershipLevel\":" + membershipLevel
682	                + ",\"event\":\"OWNER_CREATED\"}";
683	        }
684	
685	        private static String jsonString(String value) {
686	            if (value == null) {
687	                return "null";
688	            }
689	            StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
690	            for (int i = 0; i < value.length(); i++) {
691	                char c = value.charAt(i);
692	                switch (c) {
693	                    case '"' -> sb.append("\\\"");
694	                    case '\\' -> sb.append("\\\\");
695	                    case '\n' -> sb.append("\\n");
696	                    case '\r' -> sb.append("\\r");
697	                    case '\t' -> sb.append("\\t");
698	                    default -> {
699	                        if (c < 0x20) {
700	                            sb.append(String.format("\\u%04x", (int) c));
701	                        } else {
702	                            sb.append(c);
703	                        }
704	                    }
705	                }
706	            }
707	            return sb.append('"').toString();
708	        }
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Override
713	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
714	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
715	        if (currentOwner == null) {
716	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
717	        }
718	        currentOwner.setAddress(ownerFieldsDto.getAddress());
719	        currentOwner.setCity(ownerFieldsDto.getCity());
720	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
721	        currentOwner.setLastName(ownerFieldsDto.getLastName());
722	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
723	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
724	        this.clinicService.saveOwner(currentOwner);
725	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
726	    }
727	
728	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
729	    @Transactional
730	    @Override
731	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
732	        Owner owner = this.clinicService.findOwnerById(ownerId);
733	        if (owner == null) {
734	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
735	        }
736	        owner.setDeleted(true);
737	        this.clinicService.saveOwner(owner);
738	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
739	    }
740	
741	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
742	    @Override
743	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
744	        Owner owner = this.clinicService.findOwnerById(ownerId);
745	        if (owner == null) {
746	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
747	        }
748	        HttpHeaders headers = new HttpHeaders();
749	        Pet pet = petMapper.toPet(petFieldsDto);
750	        owner.setId(ownerId);
751	        pet.setOwner(owner);
752	        pet.getType().setName(null);
753	        this.clinicService.savePet(pet);
754	        PetDto petDto = petMapper.toPetDto(pet);
755	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
756	            .buildAndExpand(pet.getId()).toUri());
757	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
758	    }
759	
760	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
761	    @Override
762	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
763	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
764	        if (currentOwner != null) {
765	            Pet currentPet = this.clinicService.findPetById(petId);
766	            if (currentPet != null) {
767	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
768	                currentPet.setName(petFieldsDto.getName());
769	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
770	                this.clinicService.savePet(currentPet);
771	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
772	            }
773	        }
774	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
775	    }
776	
777	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
778	    @Override
779	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
780	        HttpHeaders headers = new HttpHeaders();
781	        Visit visit = visitMapper.toVisit(visitFieldsDto);
782	        Pet pet = new Pet();
783	        pet.setId(petId);
784	        visit.setPet(pet);
785	        this.clinicService.saveVisit(visit);
786	        VisitDto visitDto = visitMapper.toVisitDto(visit);
787	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
788	            .buildAndExpand(visit.getId()).toUri());
789	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
790	    }
791	
792	
793	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
794	    @Override
795	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
796	        Owner owner = this.clinicService.findOwnerById(ownerId);
797	        if (owner != null) {
798	            Pet pet = owner.getPet(petId);
799	            if (pet != null) {
800	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
801	            }
802	        }
803	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
804	    }
805	}
